#!/usr/bin/env bash
# generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
#
# Build an installable tarball of the app, without development files.
#
# Usage: bash scripts/package-app.sh [output.tar.gz]
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"

die() { echo "error: $*" >&2; exit 1; }

VERSION="$(sed -n 's:.*<version>\(.*\)</version>.*:\1:p' "$PROJECT_ROOT/appinfo/info.xml" | head -1)"
OUT="${1:-$PROJECT_ROOT/tmp/upm-${VERSION:-dev}.tar.gz}"

[ -f "$PROJECT_ROOT/appinfo/info.xml" ] || die "appinfo/info.xml missing"
[ -f "$PROJECT_ROOT/js/upm.js" ] ||
	die "js/upm.js is missing; run 'bash scripts/build-frontend.sh' first"

STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
mkdir -p "$STAGE/upm"

EXCLUDES=(
	--exclude node_modules
	--exclude src
	--exclude tests
	--exclude doc
	--exclude docs
	--exclude scripts
	--exclude tmp
	--exclude .dev
	--exclude .git
	--exclude .github
	--exclude .vscode
	--exclude img/screenshots
	--exclude package.json
	--exclude package-lock.json
	--exclude tsconfig.json
	--exclude vite.config.ts
	--exclude vitest.config.ts
	--exclude Makefile
	--exclude .gitignore
	--exclude .editorconfig
)

if command -v rsync >/dev/null 2>&1; then
	rsync -a --delete --delete-excluded "${EXCLUDES[@]}" "$PROJECT_ROOT/" "$STAGE/upm/"
else
	(
		cd "$PROJECT_ROOT"
		cp -a appinfo lib js img templates composer.json LICENSE README.md "$STAGE/upm/"
	)
fi

[ -f "$STAGE/upm/js/upm.js" ] || die "staging failed: js/upm.js missing"
[ -f "$STAGE/upm/appinfo/info.xml" ] || die "staging failed: appinfo/info.xml missing"

mkdir -p "$(dirname "$OUT")"
tar -czf "$OUT" -C "$STAGE" upm

echo "wrote $OUT ($(du -h "$OUT" | cut -f1))"
if command -v sha256sum >/dev/null 2>&1; then
	sha256sum "$OUT"
fi
